@HiltViewModel class FavoritesViewModel @Inject constructor(private val repository:FavoriteRepository,private val mediaRepository:MediaRepository,accountsRepository:AccountRepository,categoriesRepository:CategoryRepository):ViewModel(){val favorites=repository.observeFavorites().stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val accounts=accountsRepository.observeAccounts().map{it.filterNot(Account::isArchived)}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val categories=categoriesRepository.observeCategories(CategoryKind.EXPENSE).map{it.filterNot(Category::isArchived)}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val subs=categoriesRepository.observeSubcategories().map{it.filterNot(Subcategory::isArchived)}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());private val _result=MutableStateFlow<FavoriteClickResult?>(null);val result=_result.asStateFlow();private val _error=MutableStateFlow(false);val error=_error.asStateFlow();private val _paths=MutableStateFlow<Map<String,String>>(emptyMap());val paths=_paths.asStateFlow()
 fun save(input:FavoriteInput,done:()->Unit)=viewModelScope.launch{runCatching{repository.save(input)}.onSuccess{done()}.onFailure{_error.value=true}}
 fun media(uri:String,crop:CropMode,done:(String)->Unit)=viewModelScope.launch{runCatching{mediaRepository.importMedia(uri,crop)}.onSuccess{done(it.id);loadPath(it.id)}.onFailure{_error.value=true}}
 fun loadPath(id:String){if(id in _paths.value)return;viewModelScope.launch{mediaRepository.mediaFilePath(id)?.let{_paths.value=_paths.value+(id to it)}}}
 fun click(value:Favorite)=viewModelScope.launch{runCatching{repository.recordImmediateClick(value.id)}.onSuccess{_result.value=it}.onFailure{_error.value=true}}
 fun create(value:Favorite,quantity:Int,price:Long,date:String,request:String,done:()->Unit)=viewModelScope.launch{runCatching{repository.createOperation(value.id,request,quantity,price,date)}.onSuccess{_result.value=it;done()}.onFailure{_error.value=true}}
 fun undo(){val id=_result.value?.transactionId?:return;viewModelScope.launch{repository.undo(id);_result.value=null}}
 fun clearResult(){_result.value=null};fun clearError(){_error.value=false}}

@Composable fun FavoritesScreen(onBack:()->Unit,vm:FavoritesViewModel=hiltViewModel()){val favorites by vm.favorites.collectAsStateWithLifecycle();val accounts by vm.accounts.collectAsStateWithLifecycle();val categories by vm.categories.collectAsStateWithLifecycle();val subs by vm.subs.collectAsStateWithLifecycle();val result by vm.result.collectAsStateWithLifecycle();val paths by vm.paths.collectAsStateWithLifecycle();val error by vm.error.collectAsStateWithLifecycle();var create by remember{mutableStateOf(false)};var edit by remember{mutableStateOf<Favorite?>(null)};var pending by remember{mutableStateOf<Favorite?>(null)};val snack=remember{SnackbarHostState()};val errorText=stringResource(R.string.favorites_error);val undoText=stringResource(R.string.favorites_undo);val resultText=if(result==null)null else stringResource(R.string.favorites_click_result,result!!.quantity,com.budgetplusplus.core.designsystem.util.MoneyFormatter.format(result!!.totalMinor,"DZD"));LaunchedEffect(error){if(error){snack.showSnackbar(errorText);vm.clearError()}};LaunchedEffect(resultText){if(resultText!=null){val response=snack.showSnackbar(resultText,undoText,duration=SnackbarDuration.Short);if(response==SnackbarResult.ActionPerformed)vm.undo()else vm.clearResult()}}
 Scaffold(snackbarHost={SnackbarHost(snack)},topBar={BudgetTopAppBar(stringResource(R.string.favorites_title),onBackClick=onBack)},floatingActionButton={FloatingActionButton({create=true}){Text(stringResource(R.string.favorites_add))}}){p->if(favorites.filterNot{it.isArchived}.isEmpty())BudgetEmptyState(stringResource(R.string.favorites_empty),stringResource(R.string.favorites_empty_message),Modifier.padding(p).fillMaxSize(),actionText=stringResource(R.string.favorites_create),onAction={create=true})else LazyColumn(Modifier.padding(p).fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){items(favorites.filterNot{it.isArchived},key={it.id}){favorite->FavoriteCard(favorite,favorite.mediaId?.let(paths::get),{if(favorite.behavior==FavoriteBehavior.IMMEDIATE)vm.click(favorite)else pending=favorite},{edit=favorite}){id->vm.loadPath(id)}}}}
 if(create)FavoriteEditor(null,accounts,categories,subs,vm,{create=false}){vm.save(it){create=false}};edit?.let{value->FavoriteEditor(value,accounts,categories,subs,vm,{edit=null}){vm.save(it){edit=null}}};pending?.let{value->FavoriteQuantityDialog(value,value.behavior==FavoriteBehavior.FULL_FORM,{pending=null}){quantity,price,date,request->vm.create(value,quantity,price,date,request){pending=null}}}
}
@Composable private fun FavoriteCard(value:Favorite,path:String?,click:()->Unit,edit:()->Unit,load:(String)->Unit){LaunchedEffect(value.mediaId){value.mediaId?.let(load)};ElevatedCard(Modifier.fillMaxWidth().clickable(onClick=click)){Row(Modifier.padding(16.dp).fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(12.dp),verticalAlignment=Alignment.CenterVertically){if(path!=null){val bitmap=remember(path){android.graphics.BitmapFactory.decodeFile(path)};if(bitmap!=null)Image(bitmap.asImageBitmap(),value.name,Modifier.size(64.dp))}else Box(Modifier.size(52.dp).background(favoriteColor(value.colorKey),CircleShape),contentAlignment=Alignment.Center){Icon(BudgetIconCatalog.vector(value.iconKey),contentDescription=value.name,tint=Color.White)};Column(Modifier.weight(1f)){Text(value.name,style=MaterialTheme.typography.titleMedium);MoneyText(value.unitPriceMinor,value.currencyCode);Text(value.accountName);Text(favoriteCategory(value.categoryName))};TextButton(edit){Text(stringResource(R.string.favorites_edit))}}}}
@Composable private fun FavoriteEditor(old:Favorite?,accounts:List<Account>,categories:List<Category>,subs:List<Subcategory>,vm:FavoritesViewModel,dismiss:()->Unit,save:(FavoriteInput)->Unit){var name by remember{mutableStateOf(old?.name.orEmpty())};var price by remember{mutableStateOf(old?.unitPriceMinor?.let(::format).orEmpty())};var account by remember{mutableStateOf(old?.accountId?:accounts.firstOrNull()?.id)};var category by remember{mutableStateOf(old?.categoryId?:categories.firstOrNull()?.id)};var sub by remember{mutableStateOf(old?.subcategoryId)};var description by remember{mutableStateOf(old?.description.orEmpty())};var behavior by remember{mutableStateOf(old?.behavior?:FavoriteBehavior.QUICK_CONFIRM)};var icon by remember{mutableStateOf(old?.iconKey?:"food")};var color by remember{mutableStateOf(old?.colorKey?:"primary")};var mediaId by remember{mutableStateOf(old?.mediaId)};var iconQuery by remember{mutableStateOf("")};var theme by remember{mutableStateOf<IconTheme?>(null)};LaunchedEffect(accounts){if(account==null)account=accounts.firstOrNull()?.id};LaunchedEffect(categories){if(category==null)category=categories.firstOrNull()?.id};val parsed=parse(price);val labeledIcons=BudgetIconCatalog.icons.map{it to iconDescription(it)};val filtered=labeledIcons.filter{(definition,label)->(theme==null||definition.theme==theme)&&(iconQuery.isBlank()||label.contains(iconQuery,true))};AlertDialog(onDismissRequest=dismiss,title={Text(stringResource(if(old==null)R.string.favorites_new else R.string.favorites_edit_title))},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){item{BudgetTextField(name,{name=it},stringResource(R.string.favorites_name))};item{BudgetAmountField(price,{price=it},stringResource(R.string.favorites_price),stringResource(R.string.favorites_currency))};item{FavoriteSelector(stringResource(R.string.favorites_account),accounts,account,{it.id},{it.name}){account=it?.id}};item{FavoriteSelector(stringResource(R.string.favorites_category),categories,category,{it.id},{it.customName?:stringResource(R.string.favorites_system_category)}){category=it?.id;sub=null}};val children=subs.filter{it.categoryId==category};if(children.isNotEmpty())item{FavoriteSelector(stringResource(R.string.favorites_subcategory),children,sub,{it.id},{it.name}){sub=it?.id}};item{BudgetTextField(description,{description=it},stringResource(R.string.favorites_description))};item{LazyRow{items(FavoriteBehavior.entries){value->FilterChip(behavior==value,{behavior=value},{Text(behaviorLabel(value))},Modifier.padding(end=4.dp))}}};item{com.budgetplusplus.core.ui.MediaPickerButton({uri,crop->vm.media(uri,crop){mediaId=it}})};item{BudgetSearchBar(iconQuery,{iconQuery=it},placeholder=stringResource(R.string.favorites_search_icons))};item{LazyRow{item{FilterChip(theme==null,{theme=null},{Text(stringResource(R.string.favorites_all_themes))})};items(IconTheme.entries){value->FilterChip(theme==value,{theme=value},{Text(themeLabel(value))},Modifier.padding(start=4.dp))}}};item{LazyRow{items(filtered){(definition,desc)->FilterChip(icon==definition.key,{icon=definition.key},{Icon(BudgetIconCatalog.vector(definition.key),desc)},Modifier.padding(end=4.dp))}}};item{LazyRow{items(listOf("primary","green","orange","blue")){value->val desc=colorLabel(value);FilterChip(color==value,{color=value},{Box(Modifier.size(24.dp).background(favoriteColor(value),CircleShape).semantics{contentDescription=desc})},Modifier.padding(end=4.dp))}}}}},confirmButton={TextButton({save(FavoriteInput(old?.id,name.trim(),mediaId,icon,color,parsed!!,requireNotNull(account),requireNotNull(category),sub,description.trim(),behavior))},enabled=name.isNotBlank()&&parsed!=null&&parsed>0&&account!=null&&category!=null){Text(stringResource(R.string.favorites_save))}},dismissButton={TextButton(dismiss){Text(stringResource(R.string.favorites_close))}})}
@Composable private fun FavoriteQuantityDialog(value:Favorite,full:Boolean,dismiss:()->Unit,confirm:(Int,Long,String,String)->Unit){val request=remember{UUID.randomUUID().toString()};var quantity by remember{mutableStateOf("1")};var price by remember{mutableStateOf(format(value.unitPriceMinor))};var date by remember{mutableStateOf(LocalDate.now().toString())};val qty=quantity.toIntOrNull();val unit=parse(price);val total=if(qty!=null&&qty>0&&unit!=null)runCatching{Math.multiplyExact(unit,qty.toLong())}.getOrNull()else null;AlertDialog(onDismissRequest=dismiss,title={Text(value.name)},text={Column(verticalArrangement=Arrangement.spacedBy(8.dp)){BudgetTextField(quantity,{quantity=it.filter(Char::isDigit)},stringResource(R.string.favorites_quantity));BudgetAmountField(price,{price=it},stringResource(R.string.favorites_price),value.currencyCode);if(full)BudgetTextField(date,{date=it},stringResource(R.string.favorites_date));Text(stringResource(R.string.favorites_total));if(total!=null)MoneyText(total,value.currencyCode)}},confirmButton={TextButton({confirm(requireNotNull(qty),requireNotNull(unit),date,request)},enabled=total!=null&&runCatching{LocalDate.parse(date)}.isSuccess){Text(stringResource(R.string.favorites_validate))}},dismissButton={TextButton(dismiss){Text(stringResource(R.string.favorites_close))}})}
@Composable private fun <T> FavoriteSelector(label:String,values:List<T>,selected:String?,id:(T)->String,text: @Composable (T) -> String,choose:(T?)->Unit){var open by remember{mutableStateOf(false)};val current=values.firstOrNull{id(it)==selected};Box{OutlinedButton({open=true},Modifier.fillMaxWidth()){Text(current?.let{text(it)}?:label)};DropdownMenu(open,{open=false}){values.forEach{value->DropdownMenuItem({Text(text(value))},{choose(value);open=false})}}}}
