private fun favoriteColor(value:String)=when(value){"green"->Color(0xFF2E7D32);"orange"->Color(0xFFEF6C00);"blue"->Color(0xFF1565C0);else->Color(0xFF386A54)}
private fun format(value:Long)="${value/100}.${(value%100).toString().padStart(2,'0')}"
internal fun parse(value:String):Long?{val parts=value.trim().replace(',','.').split('.');if(parts.size>2||parts.any{part->part.any{!it.isDigit()}})return null;val major=parts[0].ifEmpty{"0"}.toLongOrNull()?:return null;val minor=parts.getOrNull(1).orEmpty();if(minor.length>2)return null;return runCatching{Math.addExact(Math.multiplyExact(major,100),minor.padEnd(2,'0').ifEmpty{"0"}.toLong())}.getOrNull()}
